def _has_network_evidence_for_url(result: ScanResult, url: str) -> bool:
    return any(
        issue.rule_code == "S310"
        and issue.severity == IssueSeverity.CRITICAL
        and issue.details.get("type") == "explicit_network_pattern"
        and issue.details.get("pattern_type") == "url"
        and issue.details.get("matched_text") == url
        for issue in result.issues
    )


def _pickle_global(module: str, name: str) -> bytes:
    return b"c" + module.encode("ascii") + b"\n" + name.encode("ascii") + b"\n"


def _pickle_binunicode8(value: bytes) -> bytes:
    return b"\x8d" + len(value).to_bytes(8, "little") + value


def _proto0_string_literal(value: bytes) -> bytes:
    literal = value.decode("latin-1").encode("unicode_escape").replace(b"'", b"\\'")
    return b"S'" + literal + b"'\n."


def _pickle_binbytes(value: bytes) -> bytes:
    return b"B" + struct.pack("<I", len(value)) + value + b"."


def _pickle_frame(payload: bytes) -> bytes:
    return b"\x95" + struct.pack("<Q", len(payload)) + payload


def _float_storage_persistent_id_payload_for_bytes(key: str | bytes, data: bytes) -> bytes:
    return _pytorch_storage_persistent_id_payload(
        key,
        size_opcode=_pickle_binint(_float_storage_element_count_for_bytes(data)),
    )


def _scan_referenced_float_storage_blob(tmp_path: Path, filename: str, storage_blob: bytes) -> ScanResult:
    model_path = tmp_path / filename
    storage_blob += b" " * (-len(storage_blob) % 4)
    with zipfile.ZipFile(model_path, "w") as zip_file:
        zip_file.writestr("archive/version", "3\n")
        zip_file.writestr("archive/byteorder", "little")
        zip_file.writestr("archive/data.pkl", _float_storage_persistent_id_payload_for_bytes("0", storage_blob))
        zip_file.writestr("archive/data/0", storage_blob)
    return PyTorchZipScanner().scan(str(model_path))


def _metadata_reduce_payload(module: str, name: str, value: bytes = b"metadata") -> bytes:
    return _pickle_global(module, name) + _pickle_binunicode(value) + b"\x85R"


def _metadata_newobj_build_payload(module: str, name: str) -> bytes:
    return _pickle_global(module, name) + b")\x81}b"


def _metadata_build_payload(module: str, name: str) -> bytes:
    return _pickle_global(module, name) + b"}b"


def _torchscript_module_build_intlist_payload() -> bytes:
    return (
        b"\x80\x02"
        + _pickle_global("__torch__", "Module")
        + b")\x81}"
        + _pickle_binunicode(b"shape")
        + _pickle_global("torch.jit._pickle", "build_intlist")
        + b"](K\x01K\x02K\x03e\x85R"
        + b"sb."
    )


