        "    'marker_after_unpickle': marker.exists(),\n"
        "    'issues': [\n"
        "        {\n"
        "            'rule_code': issue.rule_code,\n"
        "            'severity': issue.severity.value,\n"
        "            'import_reference': (issue.details or {}).get('import_reference'),\n"
        "        }\n"
