    stream += b"S'run'\n" + b"N0" * (pytorch_zip_scanner_module._MAX_RAW_NESTED_PICKLE_CANDIDATE_BYTES // 2 + 17)
    stream += b"\x940g" + str(get_key).encode() + b"\n\x93)R."
