def test_pytorch_zip_initialize_scan_does_not_read_archive_members(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    """Regression test for stale duplicate scan logic in _initialize_scan()."""
    zip_path = tmp_path / "model.pt"

    with zipfile.ZipFile(zip_path, "w") as zipf:
        zipf.writestr("archive/version", "3")
        zipf.writestr("archive/data.pkl", pickle.dumps({"weights": [1, 2, 3]}))
        zipf.writestr("archive/data/0", b"\x00" * 1024)

    archive_reads: list[str] = []

    def fail_read(
        self: zipfile.ZipFile,
        name: str | zipfile.ZipInfo,
        pwd: bytes | None = None,
    ) -> bytes:
        archive_reads.append(name.filename if isinstance(name, zipfile.ZipInfo) else str(name))
        raise AssertionError("_initialize_scan() should not read archive member payloads")

    def fail_open(
        self: zipfile.ZipFile,
        name: str | zipfile.ZipInfo,
        mode: str = "r",
        pwd: bytes | None = None,
        *,
        force_zip64: bool = False,
    ) -> IO[bytes]:
        archive_reads.append(name.filename if isinstance(name, zipfile.ZipInfo) else str(name))
        raise AssertionError("_initialize_scan() should not open archive member payloads")

    def fail_namelist(self: zipfile.ZipFile) -> list[str]:
        raise AssertionError("_initialize_scan() should not materialize all archive member names")

    def fail_zip_file(*args: Any, **kwargs: Any) -> None:
        del args, kwargs
        raise AssertionError("_initialize_scan() should not parse the ZIP central directory")

    monkeypatch.setattr(zipfile.ZipFile, "read", fail_read)
    monkeypatch.setattr(zipfile.ZipFile, "open", fail_open)
    monkeypatch.setattr(zipfile.ZipFile, "namelist", fail_namelist)
    monkeypatch.setattr(zipfile, "ZipFile", fail_zip_file)

    scanner = PyTorchZipScanner()
    result = scanner._initialize_scan(str(zip_path))

    assert result.success is True
    assert archive_reads == []
    assert "pickle_files" not in result.metadata


def test_pytorch_zip_initialize_scan_uses_prefix_hash_for_oversized_archive(
    tmp_path: Path,
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    zip_path = create_mock_pytorch_zip(tmp_path / "large.pt")
    prefix_limit = 1024
    with zip_path.open("ab") as handle:
        handle.write(b"A" * (prefix_limit * 2))

    def fail_full_hash(self: PyTorchZipScanner, path: str, result: ScanResult) -> None:
        del self, path, result
        raise AssertionError("oversized PyTorch ZIP initialization should not hash the full archive")

    monkeypatch.setattr(PyTorchZipScanner, "add_file_integrity_check", fail_full_hash)

    scanner = PyTorchZipScanner(config={"max_file_read_size": prefix_limit})
    result = scanner._initialize_scan(str(zip_path))

    integrity_check = next(check for check in result.checks if check.name == "File Integrity Hash")
    expected_prefix_hash = hashlib.sha256(zip_path.read_bytes()[:prefix_limit]).hexdigest()
    assert result.success is True
    assert result.metadata["file_hashes"] == {"sha256_prefix": expected_prefix_hash}
    assert integrity_check.details["sha256_prefix"] == expected_prefix_hash
    assert integrity_check.details["bytes_hashed"] == prefix_limit
    assert integrity_check.details["hash_complete"] is False
    assert "sha256" not in integrity_check.details


