def test_pytorch_zip_context_numeric_ownership_punctuation_names(tmp_path: Path, name_size: int, valid: bool) -> None:
    name = (b"" if valid else b"\xff") + b"!" + b"a" * name_size
    payload = b"c" + name + b"\nrun\n."
