    capacity = pytorch_zip_scanner_module._STORAGE_LITERAL_DECODED_TEXT_WINDOW_OVERLAP_BYTES
    for prefix_count in (0, capacity - 1):
        text = "一\\\n" * prefix_count + "\\" * 2 + "\n\ntail"
        expected = "一" * prefix_count + "\\\ntail"
